-- 老系统次卡数据导入 SQL
-- 生成时间: 2026-04-07 01:51:48
-- 源文件: response.json
-- 门店 org_id: 3
-- 原始次卡数: 1358
-- 唯一会员数: 871
-- 生成券实例数: 3500
-- 跳过(剩余次数=0): 608
-- 快照记录数: 1358

START TRANSACTION;

-- ============================================
-- 通用次卡模板优惠券 (vip_ticket)
-- ============================================

INSERT INTO vip_ticket (create_time, update_time, is_delete, ticket_status, ticket_name, ticket_type, ticket_effective_time, ticket_value)
SELECT NOW(), NOW(), 0, 1, '老系统次卡迁移模板', 1, -1, 0
WHERE NOT EXISTS (SELECT 1 FROM vip_ticket WHERE ticket_name = '老系统次卡迁移模板' AND is_delete = 0);

-- 门店关联 (item_type=4 优惠券)
INSERT IGNORE INTO sys_org_relation (item_type, item_id, org_id)
SELECT 4, id, 3 FROM vip_ticket WHERE ticket_name = '老系统次卡迁移模板' AND is_delete = 0;

-- 项目券关联所有门店服务项目 (vip_ticket_detail)
INSERT IGNORE INTO vip_ticket_detail (ticket_id, server_item_id)
SELECT vt.id, sor.item_id
FROM vip_ticket vt
CROSS JOIN sys_org_relation sor
WHERE vt.ticket_name = '老系统次卡迁移模板' AND vt.is_delete = 0
  AND sor.item_type = 1 AND sor.org_id = 3;

